use system.collections.list

fn sum_of_squares(items List<int>) int
    var total = 0
    for item in items
        total = total + item * item
    total

fn main()
    let nums = List([1, 2, 3, 4])
    let result = sum_of_squares(nums)
    println(f"sum of squares of {nums.size()} numbers: {result}")

